param([ValidateSet('Prepare')][string]$Mode='Prepare',[switch]$ExecutionAuthorized)
# Input preparation only; no build, GenCase, solver, reader, OFF control or follow-on action.
$ErrorActionPreference='Stop';$tests=Split-Path -Parent $PSScriptRoot;$logs=Join-Path $tests 'logs';$seed=Join-Path $tests 'outputs\upl_column_ringdown_seed_r1';$record=Join-Path $logs 'upl_column_ringdown_r1.inputs.json';$ci=[Globalization.CultureInfo]::InvariantCulture
function E([string]$p){$f=Get-Item -LiteralPath $p;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function J([string]$p){[IO.File]::ReadAllText($p)|ConvertFrom-Json}
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function V($rows){foreach($e in $rows){Need (![string]::IsNullOrEmpty($e.path)) 'Missing Entry';$a=E $e.path;Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed bound artifact: '+$e.path)}}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained path protected: '+$p)}}
function Dom([string]$p){$x=New-Object Xml.XmlDocument;$x.PreserveWhitespace=$false;$x.Load($p);return $x}
function One($x,[string]$path){$n=$x.SelectNodes($path);Need ($n.Count -eq 1) ('Expected one XML node: '+$path);return $n[0]}
function XmlText($x){Need ($x.FirstChild -is [Xml.XmlDeclaration]) 'Original XML declaration required';$declaration=$x.FirstChild.OuterXml;$s=New-Object Xml.XmlWriterSettings;$s.OmitXmlDeclaration=$true;$s.Indent=$true;$s.IndentChars='    ';$s.NewLineChars="`n";$s.NewLineHandling=[Xml.NewLineHandling]::Replace;$body=New-Object Text.StringBuilder;$w=[Xml.XmlWriter]::Create($body,$s);try{$x.Save($w)}finally{$w.Dispose()};return $declaration+"`n"+$body.ToString()}
function SaveXml($x,[string]$p){[IO.File]::WriteAllText($p,(XmlText $x),(New-Object Text.UTF8Encoding($false)))}
function NextTime([double]$t,$state,$segments){
  if($state.last_input -ge 0 -and $t -eq $state.last_input){return $state.last_output};$state.last_input=$t
  $tb=[double]$segments[$state.base].time;$nextAnchor=[double]::MaxValue;if($state.base+1 -lt $segments.Count){$nextAnchor=[double]$segments[$state.base+1].time}
  while($t -ge $nextAnchor){$state.base++;$tb=[double]$segments[$state.base].time;$nextAnchor=[double]::MaxValue;if($state.base+1 -lt $segments.Count){$nextAnchor=[double]$segments[$state.base+1].time}}
  if($t -lt $tb){$next=$tb}else{$cadence=[double]$segments[$state.base].timeout;$nt=[long][Math]::Floor(($t-$tb)/$cadence);$next=$tb+$cadence*$nt;while($next -le $t){$next=$tb+$cadence*$nt;$nt++};if($next -gt $nextAnchor){$next=$nextAnchor}}
  $state.last_output=[double]$next;return [double]$next
}
function Schedule([double]$dt,[int]$steps,[bool]$full){
  $dc=[Math]::Pow(2,-19);$factor=1;if($dt -eq [Math]::Pow(2,-20)){$factor=2};$expected=New-Object 'Collections.Generic.SortedSet[int]'
  if($full){for($k=0;$k -le 65536;$k+=64){[void]$expected.Add($k*$factor)};for($k=5120;$k -le 5376;$k++){[void]$expected.Add($k*$factor)};$segments=@(@{time=0.0;timeout=64*$dc},@{time=5120*$dc;timeout=$dc},@{time=5376*$dc;timeout=64*$dc})}else{foreach($k in 0,1,2){[void]$expected.Add($k)};$segments=@(@{time=0.0;timeout=$dt})}
  $state=@{base=0;last_input=-1.0;last_output=0.0};$rows=New-Object 'Collections.Generic.List[object]';[void]$rows.Add([ordered]@{part=0;completed_steps=0;saved_step=0;time_s=0.0});$t=0.0;$next=NextTime 0.0 $state $segments
  for($completed=1;$completed -le $steps;$completed++){$t+=$dt;if($t -ge $next -or $completed -eq $steps){[void]$rows.Add([ordered]@{part=$rows.Count;completed_steps=$completed;saved_step=$completed-1;time_s=[double]$t});$next=NextTime $t $state $segments}}
  $wanted=@($expected);Need ($rows.Count -eq $wanted.Count -and $rows.Count -eq $(if($full){1277}else{3})) 'Source-replayed sample count differs'
  for($i=0;$i -lt $wanted.Count;$i++){Need ($rows[$i].completed_steps -eq $wanted[$i] -and $rows[$i].saved_step -eq $(if($i -eq 0){0}else{$wanted[$i]-1}) -and [BitConverter]::DoubleToInt64Bits($rows[$i].time_s) -eq [BitConverter]::DoubleToInt64Bits($wanted[$i]*$dt)) 'Source replay differs from independent integer schedule/clock'}
  Need ($t -eq $steps*$dt) 'Accumulated dyadic final clock differs';if($full){Need ($rows[203].completed_steps -eq 5243*$factor -and $rows[204].completed_steps -eq 5244*$factor -and @($rows|Where-Object{$_.completed_steps -gt 5243*$factor}).Count -eq 1073) 'Declared event bracket differs'}
  return [ordered]@{table=$rows.ToArray();segments=$segments;sample_count=$rows.Count;integer_union_exact=$true;saved_step_rule_exact=$true;accumulated_clock_bits_exact=$true;final_time_s=[double]$t}
}
Need ($Mode -ceq 'Prepare' -and $ExecutionAuthorized) 'Root full-read and explicit Prepare authorization required'
$retainedPath=Join-Path $logs 'upl_column_public_r1.inputs.json';$retainedEntry=E $retainedPath;$retained=J $retainedPath;$plan=E (Join-Path $tests 'notes\upl_column_dyadic_plan_r1.json');$scheduler=E (Join-Path (Join-Path $tests '..\..\..\..\src') 'source\JDsOutputTime.cpp')
Need ($retained.stage -ceq 'upl_column_public_prepare_r1' -and $retained.prepared -eq $true -and $retained.passed -eq $true -and $retained.physical_acceptance -eq $false -and @($retained.jobs).Count -eq 3) 'Sealed public ON input preparation required'
Need ($scheduler.sha256 -ceq 'b26c1b87f090b28bdc72c28d6ed7dfeee0ad7a0bcd28eb428f1ae72716d0c72f') 'GetNextTime source differs from the fully read literal replay'
$dc=[Math]::Pow(2,-19);$eventTime=5243*$dc;$declarations=@(@{window='smoke';dt=$dc;end=2*$dc;steps=2;samples=3;sha='418ec4e70ca3fa3903e685b73c24914aca224e1ee3a94e35819903ed1504de43'},@{window='coarse';dt=$dc;end=0.125;steps=65536;samples=1277;sha='3d166d2825f9be0d594f22f4d0e2a3b10eb6cf058d08db591eb78f3e39d0cb77'},@{window='half';dt=[Math]::Pow(2,-20);end=0.125;steps=131072;samples=1277;sha='f4ce274a17bf7904cf0c5ead3197fc9c077b260484511c372d96626528b151db'})
$bindings=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_column_ringdown_prepare_r1.json')),$retainedEntry,$plan,$scheduler);$plans=@();$fresh=@($seed,$record)
foreach($d in $declarations){$windowJobs=@($retained.jobs|Where-Object{$_.window -ceq $d.window});Need ($windowJobs.Count -eq 1) 'Unique retained same-window job required';$o=$windowJobs[0];V @($o.configuration,$o.runtime,$o.initial_BI4,$o.normals)
  Need ($o.runtime.sha256 -ceq $d.sha -and $o.configuration.sha256 -ceq $d.sha -and $o.initial_BI4.sha256 -ceq 'f2836ffeb049fc777de7687608dd5dfbece81f78440bdc01f21890ee3e3fedac' -and $o.normals.sha256 -ceq '0509139e4fee0c57d3b480f213c4b9062cf467ce6a24c0a1d13d87148a885f97') 'Retained public XML/seed identity differs'
  $configuration=Join-Path $tests ('configs\upl_column_ringdown_'+$d.window+'_r1.xml');$fresh+=$configuration;$schedule=Schedule $d.dt $d.steps ($d.window -cne 'smoke');$bindings+=@($o.configuration,$o.runtime,$o.initial_BI4,$o.normals);$plans+=@{d=$d;old=$o;configuration=$configuration;schedule=$schedule}
}
$coarse=$plans[1].schedule.table;$half=$plans[2].schedule.table;for($i=0;$i -lt 1277;$i++){Need ($half[$i].completed_steps -eq 2*$coarse[$i].completed_steps -and [BitConverter]::DoubleToInt64Bits($half[$i].time_s) -eq [BitConverter]::DoubleToInt64Bits($coarse[$i].time_s)) 'Coarse/half saved clocks are not bit-paired'}
Fresh $fresh;V $bindings;$jobs=@();$files=@();$failure=$null;$unchanged=$false
try{[void](New-Item -ItemType Directory -Path $seed);foreach($p in $plans){$d=$p.d;$o=$p.old;$x=Dom $o.runtime.path;$original=$x.OuterXml;$h='/case/execution/special/hydromechanics/';foreach($check in @(@('HydroMechDynamicSeepage','1'),@('HydroMechConductivityModel','0'),@('HydroMechConductivityCk','0'))){Need ((One $x ($h+$check[0])).GetAttribute('value') -ceq $check[1]) 'Public constant-k master/material differs'}
  $changes=@(@{path='/case/execution/parameters/parameter[@key="DtIni"]';value=$d.dt},@{path='/case/execution/parameters/parameter[@key="DtFixed"]';value=$d.dt},@{path='/case/execution/parameters/parameter[@key="TimeMax"]';value=$d.end},@{path='/case/execution/parameters/parameter[@key="TimeOut"]';value=$(if($d.window -ceq 'smoke'){$dc}else{64*$dc})},@{path=$h+'HydroMechTopLoadRampTime';value=$eventTime},@{path=$h+'HydroMechDrainageStartTime';value=$eventTime})
  foreach($c in $changes){$n=One $x $c.path;$c.old_value=$n.GetAttribute('value');$c.old_comment=$n.GetAttribute('comment');$c.had_comment=$n.HasAttribute('comment');$n.SetAttribute('value',([double]$c.value).ToString('R',$ci))}
  (One $x '/case/execution/parameters/parameter[@key="TimeMax"]').SetAttribute('comment','Bounded dyadic ringdown candidate; not full consolidation acceptance');(One $x '/case/execution/parameters/parameter[@key="TimeOut"]').SetAttribute('comment',$(if($d.window -ceq 'smoke'){'Every dyadic smoke step; no special timeout'}else{'Exact dyadic default; three special segments bracket the drainage event'}))
  $special=One $x '/case/execution/special';$oldTimeout=$x.SelectSingleNode('/case/execution/special/timeout');$savedTimeout=$null;if($null -ne $oldTimeout){$savedTimeout=$oldTimeout.CloneNode($true)};Need (($d.window -ceq 'smoke' -and $null -eq $oldTimeout) -or ($d.window -cne 'smoke' -and $null -ne $oldTimeout -and $oldTimeout.SelectNodes('tout').Count -eq 4)) 'Retained timeout structure differs'
  if($d.window -cne 'smoke'){$nt=$x.CreateElement('timeout');$nt.SetAttribute('active','true');$nt.SetAttribute('comment','Exact dyadic output schedule; no clock snapping or decimal output bias');foreach($seg in $p.schedule.segments){$n=$x.CreateElement('tout');$n.SetAttribute('time',([double]$seg.time).ToString('R',$ci));$n.SetAttribute('timeout',([double]$seg.timeout).ToString('R',$ci));[void]$nt.AppendChild($n)};[void]$special.ReplaceChild($nt,$oldTimeout)}
  SaveXml $x $p.configuration;$inverse=Dom $p.configuration;foreach($c in $changes){$n=One $inverse $c.path;$n.SetAttribute('value',$c.old_value);if($c.had_comment){$n.SetAttribute('comment',$c.old_comment)}else{$n.RemoveAttribute('comment')}};if($null -ne $savedTimeout){$actual=One $inverse '/case/execution/special/timeout';[void]$actual.ParentNode.ReplaceChild($inverse.ImportNode($savedTimeout,$true),$actual)};Need ($inverse.OuterXml -ceq $original) 'Inverse DOM differs outside declared clock/event changes'
  $prefix=Join-Path $seed ('upl_column_ringdown_'+$d.window+'_r1');$runtime=$prefix+'.xml';$bi4=$prefix+'.bi4';$normal=$prefix+'_Normals.nbi4';Fresh @($runtime,$bi4,$normal);Copy-Item -LiteralPath $p.configuration -Destination $runtime;Copy-Item -LiteralPath $o.initial_BI4.path -Destination $bi4;Copy-Item -LiteralPath $o.normals.path -Destination $normal;$ce=E $p.configuration;$re=E $runtime;$be=E $bi4;$ne=E $normal
  Need ($ce.bytes -eq $re.bytes -and $ce.sha256 -ceq $re.sha256 -and $be.bytes -eq $o.initial_BI4.bytes -and $be.sha256 -ceq $o.initial_BI4.sha256 -and $ne.bytes -eq $o.normals.bytes -and $ne.sha256 -ceq $o.normals.sha256) 'Prepared runtime/retained binary copy differs'
  $jobs+=@{window=$d.window;backend_shared_runtime=$true;configuration=$ce;runtime=$re;input_prefix=$prefix;initial_BI4=$be;normals=$ne;dt_s=$d.dt;end_s=$d.end;steps=$d.steps;expected_samples=$d.samples;required_CLI=@('-mdbc_freeslip','-svres',('-nsteps:'+$d.steps));retained_manifest=$retainedEntry;retained_configuration=$o.configuration;retained_runtime=$o.runtime;retained_initial_BI4=$o.initial_BI4;retained_normals=$o.normals;declared_clock_event_only_changes=$true;inverse_DOM_exact=$true;master_value=1;conductivity_model=0;conductivity_Ck=0;initial_particle_fields_rewritten=$false;ramp_and_drain_event_s=$eventTime;event_completed_step=$(if($d.window -ceq 'half'){10486}else{5243});saved_clock_table=$p.schedule.table;special_timeout=$(@($p.schedule.segments)|Where-Object{$d.window -cne 'smoke'});scheduler_preflight=@{source=$scheduler;integer_union_exact=$true;saved_step_rule_exact=$true;accumulated_clock_bits_exact=$true;observed_native_clock=$false}};$files+=@($ce,$re,$be,$ne)
}}catch{$failure=$_.Exception.Message}
try{V $bindings;V $files;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}}
$passed=(!$failure -and $unchanged -and $jobs.Count -eq 3 -and $files.Count -eq 12);$value=[ordered]@{stage='upl_column_ringdown_prepare_r1';passed=[bool]$passed;prepared=[bool]$passed;scope='Input preparation and declared-clock replay only, not solver or physical admission';author=(E $PSCommandPath);note=(E (Join-Path $tests 'notes\upl_column_ringdown_prepare_r1.json'));plan=$plan;retained_manifest=$retainedEntry;seed_directory=$seed;jobs=$jobs;inputs=$bindings;bindings=$bindings;files=$files;declared_clock_event_only_changes=[bool]$passed;input_sources_unchanged=$unchanged;source_replayed_schedule_preflight=@{scheduler=$scheduler;coarse_samples=1277;half_samples=1277;smoke_samples=3;half_steps_twice_coarse=$true;paired_times_bit_exact=$true;full_event_part=203;first_paired_post_open_part=204;declared_post_open_saved_frames=1073;actual_drain_count_observed=$false};native_counts_declared_from_retained_XML=@{total=1040;soil=1000;fixed=40};OFF_controls_prepared=$false;GenCase_invoked=$false;solver_reader_or_build_invoked=$false;formal_files_changed=$false;physical_acceptance=$false;failure=$failure}
Fresh @($record);[IO.File]::WriteAllText($record,($value|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)));if(!$passed){throw "Prepare failed; preserve fresh partials and $record, never overwrite retained evidence"};Write-Output "Three dyadic public ON inputs prepared, no program run: $record"
